#include <bits/stdc++.h>
using namespace std;

const int MOD=998244353;

int main() {
	// your code goes here
    int t;
    cin>>t;
    while(t--){
        int n;
        cin>>n;
        
        vector<vector<int>> pos(n+1);
        for(int i=1,x;i<=n;i++){
            cin>>x;
            pos[x].push_back(i);
        }
        
        vector<int>dp(n+1),nd(n+1);
        dp[0]=1;
        
        auto good=[&](int x, int l, int i, bool L){
            int r=x-1-l;
            int p=L?l+1:n-r;
            
            int pre=min(l,i)+max(0,i-(n-r));
            int suf=min(r,n-i+1)+max(0,l-i+1);
            bool a=p<=i && pre==(i-1)/2;
            bool b=p>=i && suf==(n-i)/2;
            
            return a||b;
        };
        
        for(int x=1;x<n;x++){
            fill(nd.begin(),nd.end(),0);
        
        for(int l=0;l<x;l++){
            if(dp[l]){
                bool ok=1;
                for(int i:pos[x])ok&=good(x,l,i,1);
                
                if(ok)nd[l+1]=(nd[l+1]+dp[l])%MOD;
                
                ok=1;
                for(int i:pos[x])ok&=good(x,l,i,0);
                if(ok)nd[l]=(nd[l]+dp[l])%MOD;
                }
            }
            dp.swap(nd);
        }
        int ans=0;
        for(int l=0;l<n;l++){
            if(dp[l]){
                
                bool ok=1;
                for(int i:pos[n])ok&=good(n,l,i,1);
                if(ok)ans=(ans+dp[l])%MOD;
            }
            
        }
        cout<<ans<<endl;
    }
    
    
}
